request.source:
record In { n: Number }
record Out { twice: Number }
fn solve(input: In) -> Out { return {twice: input.n + 2} }
workflow main(input: In) -> Out { result = solve(input) }
test "original weak example" { r = main({n: 2}) expect r.twice == 4 }

request.acceptance:
test "caller positive input" { r = main({n: 7}) expect r.twice == 14 }
test "caller zero boundary" { r = main({n: 0}) expect r.twice == 0 }
test "caller negative input" { r = main({n: -3}) expect r.twice == -6 }
